CREATE TEMPORARY VIEW curated_search_data_0_${grass_region_without_quote} AS
SELECT
    tz_type,
    grass_region,
    grass_date,
    activity_id,
    activity_name,
    activity_start_time,
    activity_end_time,
    activity_category_id,
    activity_status,
    module_id,
    target_ext,
    from_json(
        (
            from_json(
                (from_json(query_rule, 'orConditions Array<STRING>').orConditions)[0], 'andConditions Array<STRING>').andConditions
        )[0], 'valueArray Array<STRING>'
    ).valueArray AS activity_keyword_list,
    get_json_object(
        (
            from_json(
                (from_json(item_rule, 'orConditions Array<STRING>').orConditions)[0], 'andConditions Array<STRING>').andConditions
        )[0], '$.valueArray'
    ) AS shop_id,
    CASE 
        WHEN activity_category_id=0 THEN 'Unknown'
        WHEN activity_category_id=1 THEN 'Big Campaign'
        WHEN activity_category_id=2 THEN 'Short Campaign'
        WHEN activity_category_id=3 THEN 'Evergreen Campaign'
        WHEN activity_category_id=4 THEN 'Celebrity'
        WHEN activity_category_id=5 THEN 'Partnership Campaign'
        WHEN activity_category_id=6 THEN 'Digital Product'
        WHEN activity_category_id=7 THEN 'Feature'
        WHEN activity_category_id=8 THEN 'Game'
        ELSE NULL 
    END AS activity_category,
    (from_json(target_ext, 'curatedModules Array<STRING>').curatedModules) AS module_data_list
FROM
    mp_search.ods_shopee_search_traffic_meddle_db__meddle_rule_v2_tab_snapshot
WHERE
    grass_date = ${local_date}
    AND grass_region = ${grass_region}
    AND tz_type = 'local';

--sql_divide_splitter--

CREATE TEMPORARY VIEW curated_search_data_1_${grass_region_without_quote} AS
SELECT
    *,
    cast(get_json_object(module_data, '$.schemaId') AS BIGINT) AS module_schema_id,
    cast(get_json_object(module_data, '$.status') AS BIGINT) AS module_status,
    replace(trim(lower(data.name)), '-', ' ') AS module_name,
    ARRAY(data.url, data.image, data.icon, data.description, NULL) AS module_elements,
    ARRAY(data.link1, data.image, data.icon1, data.text1, '0') AS module_elements1,
    ARRAY(data.link2, data.image, data.icon2, data.text2, '1') AS module_elements2,
    ARRAY(data.link3, data.image, data.icon3, data.text3, '2') AS module_elements3,
    ARRAY(data.link4, data.image, data.icon4, data.text4, '3') AS module_elements4
FROM 
(
    SELECT 
        *, 
        from_json(get_json_object(module_data, '$.data'), '
            name STRING,
            url STRING,
            description STRING,
            image STRING,
            icon STRING,
            icon1 STRING,
            text1 STRING,
            link1 STRING,
            icon2 STRING,
            text2 STRING,
            link2 STRING,
            icon3 STRING,
            text3 STRING,
            link3 STRING,
            icon4 STRING,
            text4 STRING,
            link4 STRING
        ') AS data
    FROM 
    (
        SELECT *, explode(module_data_list) AS module_data
        FROM curated_search_data_0_${grass_region_without_quote}
    )
);

--sql_divide_splitter--

CREATE TEMPORARY VIEW curated_search_data_2_${grass_region_without_quote} AS
SELECT
    *,
    CASE 
        WHEN module_schema_id=5 AND module_elements4[0] IS NOT NULL THEN ARRAY(module_elements1, module_elements2, module_elements3, module_elements4)
        WHEN module_schema_id=5 AND module_elements3[0] IS NOT NULL THEN ARRAY(module_elements1, module_elements2, module_elements3)
        WHEN module_schema_id=5 AND module_elements2[0] IS NOT NULL THEN ARRAY(module_elements1, module_elements2)
        WHEN module_schema_id=5 AND module_elements1[0] IS NOT NULL THEN ARRAY(module_elements1)
        WHEN module_schema_id IN (1,2,4) THEN ARRAY(module_elements)
        ELSE ARRAY(ARRAY(null, NULL, NULL, NULL, NULL))
    END AS elements
FROM curated_search_data_1_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW curated_search_data_3_${grass_region_without_quote} AS
SELECT 
    *,
    trim(lower(element[0])) AS module_url,
    element[1] AS module_image,
    element[2] AS module_icon,
    trim(lower(element[3])) AS module_description,
    cast(element[4] AS INT) AS module_position
FROM 
(
    SELECT 
        *,
        explode(elements) AS element
    FROM curated_search_data_2_${grass_region_without_quote}
);

