INSERT OVERWRITE TABLE ${schema}.dim_sr_data_warehouse_curated_activity_module
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT 
    activity_id,
    activity_name,
    transform(activity_keyword_list, x -> lower(x)) AS activity_keyword_list,
    cast(shop_id AS BIGINT) AS shop_id,
    activity_start_time,
    activity_end_time,
    activity_category_id,
    CASE 
        WHEN activity_category_id=0 THEN 'Unknown'
        WHEN activity_category_id=1 THEN 'Big Campaign'
        WHEN activity_category_id=2 THEN 'Short Campaign'
        WHEN activity_category_id=3 THEN 'Evergreen Campaign'
        WHEN activity_category_id=4 THEN 'Celebrity'
        WHEN activity_category_id=5 THEN 'Partnership Campaign'
        WHEN activity_category_id=6 THEN 'Digital Product'
        WHEN activity_category_id=7 THEN 'Feature'
        WHEN activity_category_id=8 THEN 'Game'
        ELSE NULL 
    END AS activity_category,
    activity_status,
    NULL AS is_brand,

    module_id,
    module_schema_id,
    module_status,
    module_name,
    module_url,
    module_description,
    module_position
FROM
    curated_search_data_3_${grass_region_without_quote};
